import { useState } from 'react'
let Calculatrice = () => {
const [valA, setValeurA] = useState('');
const [valB, setValeurB] = useState('');
const [resultat, setResultat] = useState('');
const [message, setMessage] = useState('');
const calculer =(op)=>{
    const x=num(valA);
    const y=num(valB);
    if (op==="+") setResultat(x+y)
    if (op==="-") setResultat(x-y)
    if (op==="*") setResultat(x*y)
    if (op==="+") setResultat( y!==0? x/y :"Erreur");

}
const reset =()=>{
    setValeurA("");
    setValeurB("");
    setResultat("");
};

return(
    <div>
        <h1>Calculatrice</h1>
        <label>valeurA</label>
        <input type='text'onChange={(e)=>setValA(e.target.value)}></input>
        <label>valeurB</label>
        <input type='text' onChange={(e)=>setValB(e.target.value)}></input>
        <button type="button" onClick={(calculer) => ("+")}>+</button>
        <button type="button" onClick={(calculer) =>("*")}>*</button>
        <button type="button" onClick={(calculer)=>("-")}>-</button>
        <button type="button" onClick={(calculer)=>("/")}>/</button>
        <button type="button" onClick={(reset)}>renitialiser</button>
        <p>resultat {resultat} </p>

    </div> 

)}
